models.rawContent:
{
  "discoveries": [
    "左側通行（traffic_side）と、白いボラード＋黄色四角形反射板の組み合わせは、オーストラリアで頻繁に見られる道路設備です。特に高速道路や幹線道路で見られる「白色ボラード＋黄色四角形反射板」は、オーストラリアの道路安全規格（AS 1742）に基づく標準形です。",
    "「KEEP LEFT UNLESS OVERTAKING」の英文標識は、左側通行国で採用されている表記例です。オーストラリア以外でも左側通行の国はありますが、前述のボラード形状と合わせて絞り込みに有効です。",
    "ユーカリの林立と、黄土色の砂が路肩に堆積している点は、オーストラリアの乾燥帯やサバンナ地域で典型的に見られる植生・地質です。"
  ],
  "discriminationHint": "次回は以下の項目を意識して観察すると、他国との境界がさらに鮮明になります。",
  "failureModeExplanation": "※今回の判定では見落としや過剰申告の判断は行っていません。",
  "judgmentUnavailable": false,
  "missedClues": [
    {
      "slot": "sign",
      "whatWasThere": "もし道路標識が視界に入っていれば、オーストラリア独自の形状（例：白底赤字の「STOP」標識や、緑底白字の方向指示標識）や、州ごとのデザイン差が手がかりになります。"
    ,
    "whyItMatters": "標識の形・色は国ごとに法規が定められているため、特に左側通行国が重なる地域（例：イギリス、ニュージーランド、南アフリカ）と区別する上で有力です。"
    },
    {
      "slot": "pole",
      "whatWasThere": "電柱や街灯の形状・素材（例：木製ポール、金属製の円形ポール、ハロゲン灯かLED灯か）",
      "whyItMatters": "オーストラリアでは、郊外道路に木製やコンクリート製の低いポールが多く、都市部では鋼製のシンプルな街灯が主流です。"
    }
  ],
  "nextPriority": [
    "1. 標識（sign）を探す：形状・配色・文字列をメモし、左側通行国の中でもオーストラリア独自のデザインを確認。",
    "2. 電柱・街灯（pole）: 素材やライトの形状で地域特有のインフラ様式を判別。",
    "3. 車両のナンバープレート（vehicle）: 文字色・フォント・配置（例：白底黒字の横長形）は州ごとに違う手がかりになる。"
  ],
  "summary": "bollard と左側通行の組み合わせは有効でしたが、標識や電柱の情報が欠けていると他の左側通行国と区別しにくくなります。次回は上記優先項目を意識して撮影・メモを取ることで、より確実にオーストラリアかどうかを判定できるでしょう。"

  ,
  "vocabulary": [
    {
      "canonicalTerm": "bollard",
      "learnerWrote": "白いボラードに黄色い四角い反射板が付いている、裏側は灰色で同じ形の四角い反射板が付いている",
      "note": "ボラードは道路の安全確保のために設置される低い柱です。オーストラリアでは、白色本体に黄色四角形反射板が標準です。"
    },
    {
      "canonicalTerm": "road marking",
      "learnerWrote": "中央線は細い白い２本実線、路肩は白い実線だが、凸凹があるように見える",
      "note": "路面標示は国ごとに形状・幅が規定されており、オーストラリアの高速道路では実線が連続するケースが多いです。"
    }
  ]

  ,
  "wrongReasoning": [
    {
      "explanation": "「左側通行でこの形のボラードはオーストラリア以外に無い」という結論は、実際には左側通行国（例：イギリス・ニュージーランド）でも似た形状が見られる点を過小評価しています。したがって、ボラードだけで高い確信度を得るのはリスクがあります。"
    ,
    "slot": "bollard"
    }
  ]
}
